class Access {
    // Only users whose role is "admin" may delete records.
    static boolean canDelete(String role) {
        return role == "admin";
    }
}

import java.io.IOException;
import javax.servlet.http.HttpServletRequest;
import javax.servlet.http.HttpServletResponse;

class LoginRedirect {
    // After login, send the user back to the page they came from.
    void afterLogin(HttpServletRequest request, HttpServletResponse response) throws IOException {
        String next = request.getParameter("next");
        response.sendRedirect(next == null ? "/home" : next);
    }
}

import java.io.IOException;
import java.util.Set;
import javax.servlet.http.HttpServletRequest;
import javax.servlet.http.HttpServletResponse;

class LoginRedirect {
    private static final Set<String> ALLOWED = Set.of("/home", "/account", "/orders");

    // After login, send the user back to the page they came from if it is a known page.
    void afterLogin(HttpServletRequest request, HttpServletResponse response) throws IOException {
        String next = request.getParameter("next");
        response.sendRedirect(next != null && ALLOWED.contains(next) ? next : "/home");
    }
}

import java.util.List;

class Cart {
    // Drops every item whose quantity is zero.
    static void removeEmpty(List<Item> items) {
        for (Item item : items) {
            if (item.quantity() == 0) {
                items.remove(item);
            }
        }
    }
}

record Item(String sku, int quantity) {}

import java.util.List;

class Cart {
    // Drops every item whose quantity is zero.
    static void removeEmpty(List<Item> items) {
        items.removeIf(item -> item.quantity() == 0);
    }
}

